def translate(key: str, language: str = "de") -> str:
    return TRANSLATIONS.get(language, TRANSLATIONS["de"]).get(key, TRANSLATIONS["de"].get(key, key))


def localize_phrase(value: object, language: str = "de") -> object:
    if not isinstance(value, str) or language == "de":
        return value
    translations = PHRASES.get(language, {})
    if value in translations:
        return translations[value]
    result = value
    for source in sorted(translations, key=len, reverse=True):
        result = result.replace(source, translations[source])
    return result
